using System;using System.IO;using System.Linq;using System.Reflection;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityGroundTextureVerify{const string R="FinalEnvironmentRoadReview/CityGroundTexture";static CityGroundTextureVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityGroundTextureVerify.request"))return;File.Delete("CityGroundTextureVerify.request");try{Run();}catch(Exception e){File.WriteAllText(R+"Verified.txt",e.ToString());Debug.LogException(e);}}
static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var host=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var map=host.GetComponent<CityGroundTextureLayout>();if(!map||map.plots.Any(p=>!p.renderer))throw new Exception("Missing ground mapping / renderer reference");map.Apply();var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);Action<Vector3,Vector3,string> Capture=(p,t,n)=>cap.Invoke(null,new object[]{scene,p,t,n});try{ctrl.ApplyDay();map.Apply();int cafe=0,fuel=0;foreach(var p in map.plots.Where(p=>p.data.x==2)){cafe++;var c=new Vector3(p.feature0.x,p.renderer.bounds.max.y,p.feature0.y);Capture(c+new Vector3(0,37,75),c+Vector3.up*3,"City-Ground-Cafe-"+cafe+"-Front");Capture(c+new Vector3(1,92,.5f),c,"City-Ground-Cafe-"+cafe+"-Top");}foreach(var p in map.plots.Where(p=>p.data.x==3||p.data.x==7)){fuel++;var f0=p.data.x==7?p.fuel0:p.feature0;var f1=p.data.x==7?p.fuel1:p.feature1;var c=new Vector3(f0.x,p.renderer.bounds.max.y,f0.y);var n=new Vector3(f1.x,0,f1.y);var side=Vector3.Cross(Vector3.up,n);Capture(c+n*(fuel==2?48:72)+Vector3.up*(fuel==2?32:31),c+n*5,"City-Ground-Fuel-"+fuel);}
var gen=map.plots.Where(p=>p.data.x==1&&p.data.z>0).ToArray();int i=0;foreach(var target in new[]{new Vector2(-280,-630),new Vector2(-150,-350),new Vector2(530,370),new Vector2(-390,390)}){var p=gen.OrderBy(p=>Vector2.Distance(new Vector2(p.rect.x,p.rect.y),target)).First();var patch=p.patches[0];var c=new Vector3(patch.x,p.renderer.bounds.max.y,patch.y);Capture(c+new Vector3(1,110,0.5f),c,"City-Ground-District-"+(++i));}ctrl.ApplyNight();map.Apply();var cp=map.plots.First(p=>p.data.x==2);var cc=new Vector3(cp.feature0.x,cp.renderer.bounds.max.y,cp.feature0.y);Capture(cc+new Vector3(0,30,65),cc+Vector3.up*3,"City-Ground-Cafe-Night");}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();map.Apply();}
foreach(var row in File.ReadAllLines(R+"MeshHashes.txt")){var a=row.Split('|');using(var sha=SHA256.Create()){var hash=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(a[0])));if(hash!=a[1])throw new Exception("Original mesh / UV data changed: "+a[0]);}}
int newM=AssetDatabase.FindAssets("t:Material",new[]{"Assets"}).Except(File.ReadAllLines(R+"MaterialIDs.txt")).Count(),newT=AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets"}).Except(File.ReadAllLines(R+"TextureIDs.txt")).Count();var mats=map.plots.Select(p=>p.renderer.sharedMaterial).Distinct().ToArray();bool blocks=true;foreach(var p in map.plots){var b=new MaterialPropertyBlock();p.renderer.GetPropertyBlock(b);if(Mathf.Abs(b.GetVector("_GroundData").x-p.data.x)>.01)blocks=false;}if(newM>0||newT>0||!blocks||mats.Length!=1||ShaderUtil.ShaderHasError(mats[0].shader))throw new Exception("Atlas/material/property validation failed");
string prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(host);bool validPrefab=false;var contents=PrefabUtility.LoadPrefabContents(prefab);try{var cm=contents.GetComponent<CityGroundTextureLayout>();validPrefab=cm&&cm.plots.Length==map.plots.Length&&cm.plots.All(p=>p.renderer);if(!validPrefab)throw new Exception("Prefab mappings missing");}finally{PrefabUtility.UnloadPrefabContents(contents);}
File.WriteAllText(R+"Verified.txt","SUCCESS layouts="+map.plots.Length+" cafe sites="+map.plots.Count(p=>p.data.x==2)+" fuel sites="+map.plots.Count(p=>p.data.x==3||p.data.x==7)+" shared existing material count="+mats.Length+" new material assets="+newM+" new texture assets="+newT+" original mesh files / UV data unchanged=True property blocks="+blocks+" reusable city prefab references="+validPrefab+" shader errors=False. Ground atlas same original GUID="+AssetDatabase.AssetPathToGUID("Assets/Scenes/Oasis/3D/Texture/Road/ChatGPT Image Sep 1, 2026, 03_35_01 PM.png")+". 2 cafe front/top pairs, 2 fuel forecourts, 4 district views, 1 night view captured; all grass is texture-only on existing surfaces. No new renderers / geometry / lights / plants.");EditorSceneManager.SaveScene(scene);}
}
